from __future__ import annotations

import json
from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .accounts import AccountStore
from .branding import PRODUCT_FULL_NAME, TAGLINE
from .plans import get_plan

router = APIRouter()
store = AccountStore()
COOKIE_NAME = "lss_session"


@router.get("/studio", response_class=HTMLResponse)
def studio(request: Request):
    user = store.resolve_session(request.cookies.get(COOKIE_NAME))
    if not user:
        return RedirectResponse("/signin", status_code=303)
    if user.get("status") != "active":
        return RedirectResponse("/dashboard", status_code=303)

    plan = get_plan(user.get("plan_id") or "free")
    features_json = json.dumps(sorted(plan.features))
    display_name = escape(user.get("display_name") or "Member")
    plan_name = escape(plan.name)
    daily = "Unlimited" if plan.confirmed_songs_per_day is None else str(plan.confirmed_songs_per_day)

    page = r"""<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Studio — __PRODUCT__</title>
<style>
:root{--bg:#08060d;--panel:#15101d;--panel2:#20142b;--line:#3b2b47;--gold:#e7bd63;--text:#fff;--muted:#c9bed1;--good:#7edda4;--bad:#ff91a4;--blue:#86b9ff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#1d0e2c,#08060d 460px);color:var(--text);font-family:Inter,system-ui,sans-serif}button,input,textarea,select{font:inherit}a{color:inherit}.wrap{max-width:1500px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:10px 0 20px}.brand b{color:var(--gold);display:block;font-size:.77rem;letter-spacing:.13em;text-transform:uppercase}.brand h1{font-size:1.45rem;margin:3px 0}.pill{border:1px solid var(--line);background:#21162b;border-radius:99px;padding:8px 12px;color:var(--gold);font-weight:900}.btn,button{border:1px solid var(--line);background:#22172c;color:#fff;padding:10px 14px;border-radius:11px;font-weight:800;cursor:pointer;text-decoration:none}.primary{background:linear-gradient(135deg,#f0d07c,#c7973e)!important;color:#170f1d!important;border:0!important}.layout{display:grid;grid-template-columns:245px 1fr;gap:16px}.side,.panel{background:#120d19;border:1px solid var(--line);border-radius:18px;padding:16px}.side button,.side a{width:100%;text-align:left;margin:4px 0;display:block;background:transparent}.side button.active{background:#2d1c39;color:var(--gold)}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.card{background:#18101f;border:1px solid var(--line);border-radius:16px;padding:16px}.card h3{margin:0 0 7px}.muted{color:var(--muted)}.field{margin:12px 0}.field label{display:block;font-size:.88rem;font-weight:800;margin-bottom:6px}input,textarea,select{width:100%;background:#0a0710;color:#fff;border:1px solid var(--line);padding:11px;border-radius:10px}textarea{min-height:110px;resize:vertical}.status{white-space:pre-wrap;background:#09070d;border:1px solid #2e2238;border-radius:12px;padding:13px;min-height:55px;overflow:auto}.locked{opacity:.4;position:relative}.locked:after{content:'Upgrade required';position:absolute;right:10px;top:10px;background:#4b2b54;padding:5px 8px;border-radius:99px;font-size:.7rem}.asset{padding:9px;border-bottom:1px solid #ffffff0d;cursor:pointer}.asset.selected{background:#2a1b34}.asset small{color:var(--muted)}.row{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.row>*{flex:1}.row button,.row .btn{flex:0 0 auto}.gold{color:var(--gold)}.success{color:var(--good)}.error{color:var(--bad)}.job{border-left:4px solid #634a75}.job.running{border-color:var(--blue)}.job.completed{border-color:var(--good)}.job.failed{border-color:var(--bad)}.job .state{text-transform:uppercase;font-size:.72rem;font-weight:950;letter-spacing:.08em}.progress{height:8px;background:#2d2135;border-radius:99px;overflow:hidden;margin:8px 0}.progress i{display:block;height:100%;background:linear-gradient(90deg,#8b4cc2,#e8bd62);animation:pulse 1.4s infinite alternate}@keyframes pulse{from{width:28%}to{width:88%}}@media(max-width:900px){.layout,.grid,.grid2{grid-template-columns:1fr}.side{display:flex;overflow:auto;gap:6px}.side button,.side a{min-width:max-content;width:auto}.top{align-items:flex-start}}
</style></head><body><div class="wrap">
<div class="top"><div class="brand"><b>Elevate Souls Productions Presents</b><h1>The Live Sound Studio</h1><span class="muted">__TAGLINE__ · Aura AI Producer</span></div><div class="row"><span class="pill">__PLAN__ · __DAILY__ confirmed/day</span><a class="btn" href="/aura">🎙 Talk to Aura</a><a class="btn" href="/dashboard">Account</a><form method="post" action="/signout"><button>Sign out</button></form></div></div>
<div class="layout"><nav class="side"><button class="active" data-view="create">✨ Create</button><button data-view="projects">🎚 Projects</button><button data-view="jobs">⚙ Render Queue</button><button data-view="producer">💬 Aura Producer</button><button data-view="upload">📥 Upload</button><button data-view="engineering">🧪 Engineering</button><button data-view="internet">🌐 Aura Internet</button><a class="btn" href="/aura">🎙 Spoken Aura</a></nav><main class="panel">
<section id="view-create" class="view active"><h2>Create real music</h2><p class="muted">Hello __NAME__. Describe the song, use your own lyrics or let Aura draft original lyrics, then render through the real-audio production queue.</p><div class="grid2"><div><div class="field"><label>Title</label><input id="title" placeholder="My New Song"></div><div class="field"><label>Concept / story</label><textarea id="concept" placeholder="What should the song be about?"></textarea></div><div class="field"><label>Lyrics</label><textarea id="lyrics" placeholder="Paste lyrics, or leave blank and enable Aura lyrics"></textarea></div><div class="row"><label><input id="generateLyrics" type="checkbox" style="width:auto"> Aura creates original lyrics</label><label><input id="instrumental" type="checkbox" style="width:auto"> Instrumental</label></div></div><div><div class="row"><div class="field"><label>Genre</label><input id="genre" value="pop"></div><div class="field"><label>Mood</label><input id="mood" value="uplifting"></div></div><div class="row"><div class="field"><label>BPM</label><input id="bpm" type="number" placeholder="Optional"></div><div class="field"><label>Key</label><input id="key" placeholder="Optional"></div></div><div class="field"><label>Instruments</label><input id="instruments" placeholder="real drums, bass, acoustic guitar, piano, strings"></div><div class="field"><label>Production direction</label><textarea id="extra" placeholder="Big cinematic chorus, intimate verse, live-room drums..."></textarea></div><button class="primary" onclick="createSong()">Create project</button></div></div><div id="createStatus" class="status"></div></section>
<section id="view-projects" class="view"><div class="row"><div><h2>My private projects</h2><p class="muted">Your project namespace is isolated from every other member.</p></div><button onclick="refreshProjects()">Refresh</button></div><div id="projectList" class="grid"></div><div class="card" style="margin-top:14px"><h3 id="projectTitle">Select a project</h3><div class="row"><button class="primary feature-full_track" onclick="produceSelected()">Queue Generate / Regenerate</button><button class="feature-full_track" onclick="confirmSelected()">I’m Happy — Confirm Track</button><button onclick="analyzeSelected()">Analyze</button><button onclick="refreshAssets()">Assets</button></div><div id="projectStatus" class="status"></div><div id="assetsList"></div></div></section>
<section id="view-jobs" class="view"><div class="row"><div><h2>Aura production queue</h2><p class="muted">Long neural renders run outside the web request. Pro jobs receive priority scheduling.</p></div><button onclick="refreshJobs()">Refresh</button></div><div id="jobList" class="grid"></div></section>
<section id="view-producer" class="view"><h2>Talk to Aura</h2><p class="muted">Aura uses the private local reasoning model when available and falls back safely if it is offline.</p><div class="field"><label>Current project</label><select id="producerProject"></select></div><div class="field"><label>Producer request</label><textarea id="producerText" placeholder="Make the chorus bigger, add wide guitars and backing harmonies..."></textarea></div><button class="primary" onclick="producerPlan()">Ask Aura</button><div id="producerStatus" class="status"></div></section>
<section id="view-upload" class="view"><h2>Upload material</h2><p class="muted">Audio, scores, MIDI/MusicXML control data, video and approved model files are fingerprinted and tied to a rights record.</p><div class="field"><label>Project</label><select id="uploadProject"></select></div><div class="field"><label>File</label><input id="uploadFile" type="file"></div><div class="field"><label>Tags</label><input id="uploadTags" placeholder="reference, vocal, guitar, score"></div><label><input id="rightsCheck" type="checkbox" style="width:auto"> I confirm I have the right to use this material.</label><br><br><button class="primary feature-upload_audio" onclick="uploadAsset()">Upload to project</button><div id="uploadStatus" class="status"></div></section>
<section id="view-engineering" class="view"><h2>Studio engineering</h2><p class="muted">Select a project and audio asset under Projects → Assets first.</p><div class="grid"><div class="card feature-basic_mastering"><h3>Mastering</h3><p class="muted">Streaming/basic mastering on Base; reference and advanced workflows on Pro.</p><button onclick="masterSelected()">Master selected audio</button></div><div class="card feature-audio_cleanup"><h3>Audio cleanup</h3><p class="muted">High-pass, hum removal and optional neural restoration.</p><button onclick="restoreSelected()">Clean selected audio</button></div><div class="card feature-stem_splitter"><h3>Splitter</h3><p class="muted">Separate vocals, drums, bass and instruments.</p><button onclick="splitSelected()">Split selected audio</button></div><div class="card feature-neural_amp"><h3>Neural Amp</h3><p class="muted">Run guitar or bass through an approved NAM/ONNX capture.</p><button onclick="note('Upload/select a .nam or .onnx model asset, then use Neural Amp processing.')">Workflow</button></div><div class="card feature-spatial_audio"><h3>Spatial audio</h3><p class="muted">Stereo positioning and configured immersive rendering.</p><button onclick="spatialSelected()">Create wide stereo</button></div><div class="card feature-video_sync"><h3>Video sync</h3><p class="muted">Map scene cuts to musical beats for scoring workflows.</p><button onclick="note('Upload a video and audio asset to build a scene/beat sync map.')">Workflow</button></div></div><div id="engineeringStatus" class="status"></div></section>
<section id="view-internet" class="view"><h2>Aura Internet</h2><p class="muted">Controlled research through the protected Web Gateway and private self-hosted SearXNG service.</p><div class="row"><input id="webQuery" placeholder="Search music technology, production techniques, model documentation..."><button class="primary" onclick="webSearch()">Search</button></div><div id="webStatus" class="status"></div></section>
</main></div></div>
<script>
const FEATURES=new Set(__FEATURES__);let selectedProject=null,selectedAsset=null,projects=[],activePollers=new Map();
function out(id,value,ok=true){const el=document.getElementById(id);el.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);el.className='status '+(ok?'success':'error')}
function note(v){out('engineeringStatus',v)}
function applyLocks(){document.querySelectorAll('[class*=feature-]').forEach(el=>{const cls=[...el.classList].find(x=>x.startsWith('feature-'));if(cls&&!FEATURES.has(cls.substring(8))){el.classList.add('locked');if('disabled'in el)el.disabled=true}})}
document.querySelectorAll('.side button[data-view]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.side button[data-view]').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById('view-'+btn.dataset.view).classList.add('active');if(btn.dataset.view==='jobs')refreshJobs()});
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options});let body;try{body=await r.json()}catch{body=await r.text()}if(!r.ok)throw new Error(typeof body==='string'?body:(body.detail||JSON.stringify(body)));return body}
async function refreshProjects(){try{projects=await api('/projects');const root=document.getElementById('projectList');root.innerHTML='';for(const p of projects){const d=document.createElement('div');d.className='card';d.innerHTML='<h3></h3><p class="muted"></p><button>Select</button>';d.querySelector('h3').textContent=p.name;d.querySelector('p').textContent=(p.has_manifest?'Ready':'Project')+(p.has_session?' · multitrack session':'');d.querySelector('button').onclick=()=>selectProject(p.name);root.appendChild(d)}syncProjectSelects()}catch(e){out('projectStatus',e.message,false)}}
function syncProjectSelects(){for(const id of ['producerProject','uploadProject']){const s=document.getElementById(id);s.innerHTML='';for(const p of projects){const o=document.createElement('option');o.value=p.name;o.textContent=p.name;s.appendChild(o)}}}
function selectProject(name){selectedProject=name;selectedAsset=null;document.getElementById('projectTitle').textContent=name;out('projectStatus','Selected '+name);refreshAssets()}
async function createSong(){try{const title=document.getElementById('title').value.trim();if(!title)throw new Error('Enter a song title');const payload={title,concept:document.getElementById('concept').value,lyrics:document.getElementById('lyrics').value,generate_lyrics:document.getElementById('generateLyrics').checked,genre:document.getElementById('genre').value,mood:document.getElementById('mood').value,instruments:document.getElementById('instruments').value.split(',').map(x=>x.trim()).filter(Boolean),bpm:Number(document.getElementById('bpm').value)||null,key:document.getElementById('key').value||null,vocal_mode:document.getElementById('instrumental').checked?'instrumental':'ai_vocal',extra_prompt:document.getElementById('extra').value};const r=await api('/songs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});out('createStatus',r);await refreshProjects();selectProject(r.project)}catch(e){out('createStatus',e.message,false)}}
async function produceSelected(){if(!selectedProject)return out('projectStatus','Select a project first',false);try{out('projectStatus','Submitting to Aura production queue...');const job=await api('/projects/'+encodeURIComponent(selectedProject)+'/render-jobs',{method:'POST'});out('projectStatus','Queued job '+job.id+' — '+job.status);pollJob(job.id,true);refreshJobs()}catch(e){out('projectStatus',e.message,false)}}
async function pollJob(id,projectPanel=false){if(activePollers.has(id))return;activePollers.set(id,true);let ticks=0;try{while(ticks++<1800){const job=await api('/jobs/'+encodeURIComponent(id));if(projectPanel)out('projectStatus',{job_id:job.id,status:job.status,project:job.project_name,error:job.error||null,result:job.result||null},job.status!=='failed');if(job.status==='completed'){if(projectPanel){await refreshAssets();out('projectStatus',job.result||job)}break}if(job.status==='failed'||job.status==='cancelled')break;await new Promise(r=>setTimeout(r,2000))}}catch(e){if(projectPanel)out('projectStatus',e.message,false)}finally{activePollers.delete(id);refreshJobs()}}
async function refreshJobs(){try{const jobs=await api('/jobs?limit=30');const root=document.getElementById('jobList');root.innerHTML='';if(!jobs.length){root.innerHTML='<div class="card muted">No production jobs yet.</div>';return}for(const j of jobs){const d=document.createElement('div');d.className='card job '+j.status;const state=document.createElement('div');state.className='state';state.textContent=j.status;const h=document.createElement('h3');h.textContent=j.project_name;const p=document.createElement('p');p.className='muted';p.textContent='Job '+j.id.slice(0,10)+' · priority '+j.priority;d.append(state,h,p);if(j.status==='queued'||j.status==='running'){const bar=document.createElement('div');bar.className='progress';bar.innerHTML='<i></i>';d.appendChild(bar);const b=document.createElement('button');b.textContent='Watch';b.onclick=()=>pollJob(j.id,true);d.appendChild(b)}if(j.status==='completed'){const b=document.createElement('button');b.textContent='Open project';b.onclick=()=>{selectProject(j.project_name);document.querySelector('[data-view="projects"]').click()};d.appendChild(b)}if(j.error){const e=document.createElement('p');e.className='error';e.textContent=j.error;d.appendChild(e)}root.appendChild(d)}}catch(e){document.getElementById('jobList').innerHTML='<div class="card error">'+e.message+'</div>'}}
async function confirmSelected(){if(!selectedProject)return;try{const r=await api('/projects/'+encodeURIComponent(selectedProject)+'/confirm-song',{method:'POST'});out('projectStatus',r)}catch(e){out('projectStatus',e.message,false)}}
async function analyzeSelected(){if(!selectedProject)return;try{out('projectStatus',await api('/projects/'+encodeURIComponent(selectedProject)+'/analyze',{method:'POST'}))}catch(e){out('projectStatus',e.message,false)}}
async function refreshAssets(){if(!selectedProject)return;try{const items=await api('/projects/'+encodeURIComponent(selectedProject)+'/assets');const root=document.getElementById('assetsList');root.innerHTML='<h3>Assets</h3>';for(const a of items){const d=document.createElement('div');d.className='asset';d.innerHTML='<b></b><br><small></small>';d.querySelector('b').textContent=a.name;d.querySelector('small').textContent=a.kind+' · '+a.id;d.onclick=()=>{document.querySelectorAll('.asset').forEach(x=>x.classList.remove('selected'));d.classList.add('selected');selectedAsset=a;out('projectStatus','Selected asset: '+a.name)};root.appendChild(d)}}catch(e){out('projectStatus',e.message,false)}}
async function producerPlan(){const p=document.getElementById('producerProject').value;if(!p)return out('producerStatus','Create/select a project first.',false);try{out('producerStatus',await api('/projects/'+encodeURIComponent(p)+'/producer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request:document.getElementById('producerText').value})}))}catch(e){out('producerStatus',e.message,false)}}
async function uploadAsset(){const p=document.getElementById('uploadProject').value,f=document.getElementById('uploadFile').files[0];if(!p)return out('uploadStatus','Create/select a project first.',false);if(!f)return out('uploadStatus','Choose a file',false);if(!document.getElementById('rightsCheck').checked)return out('uploadStatus','Rights confirmation is required',false);const form=new FormData();form.append('file',f);form.append('kind','auto');form.append('rights_basis','user_owned_or_licensed');form.append('attestation','I confirm I have the right to use this material in this project.');form.append('tags',document.getElementById('uploadTags').value);try{out('uploadStatus',await api('/projects/'+encodeURIComponent(p)+'/assets',{method:'POST',body:form}));if(p===selectedProject)refreshAssets()}catch(e){out('uploadStatus',e.message,false)}}
function selectedAudio(){if(!selectedProject||!selectedAsset||selectedAsset.kind!=='audio'){out('engineeringStatus','Select an audio asset in Projects first.',false);return null}return selectedAsset}
async function masterSelected(){const a=selectedAudio();if(!a)return;try{out('engineeringStatus',await api('/projects/'+encodeURIComponent(selectedProject)+'/master?asset_id='+encodeURIComponent(a.id)+'&preset=streaming',{method:'POST'}))}catch(e){out('engineeringStatus',e.message,false)}}
async function restoreSelected(){const a=selectedAudio();if(!a)return;try{out('engineeringStatus',await api('/projects/'+encodeURIComponent(selectedProject)+'/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:a.id,highpass_hz:35,neural:true})}))}catch(e){out('engineeringStatus',e.message,false)}}
async function splitSelected(){const a=selectedAudio();if(!a)return;try{out('engineeringStatus',await api('/projects/'+encodeURIComponent(selectedProject)+'/separate?asset_id='+encodeURIComponent(a.id)+'&mode=six_stems',{method:'POST'}))}catch(e){out('engineeringStatus',e.message,false)}}
async function spatialSelected(){const a=selectedAudio();if(!a)return;try{out('engineeringStatus',await api('/projects/'+encodeURIComponent(selectedProject)+'/spatial',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset_id:a.id,mode:'stereo',pan:0,width:1.5})}))}catch(e){out('engineeringStatus',e.message,false)}}
async function webSearch(){try{const r=await api('/web/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:document.getElementById('webQuery').value,limit:8})});let text='';for(const x of r.results)text+='\n'+x.title+'\n'+x.url+'\n'+x.content+'\n';out('webStatus',text.trim()||'No results')}catch(e){out('webStatus',e.message,false)}}
applyLocks();refreshProjects();refreshJobs();setInterval(()=>{const visible=document.getElementById('view-jobs').classList.contains('active');if(visible)refreshJobs()},5000);
</script></body></html>"""

    page = (
        page.replace("__PRODUCT__", escape(PRODUCT_FULL_NAME))
        .replace("__TAGLINE__", escape(TAGLINE))
        .replace("__PLAN__", plan_name)
        .replace("__DAILY__", escape(daily))
        .replace("__NAME__", display_name)
        .replace("__FEATURES__", features_json)
    )
    return HTMLResponse(page)
